import { FormEvent, ReactNode, useState } from 'react';
import {
  ArrowRight, Bell, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight,
  ClipboardCheck, Clock3, GraduationCap, LayoutDashboard, LogOut, Plus, Search, Send,
  Settings2, ShieldCheck, Users, X, XCircle, CheckCircle2, FileText,
  BarChart3, UserRound, Megaphone, Home, FileCheck2, History,
} from 'lucide-react';
import { accounts, announcements as initialAnnouncements, homework, schedule, schools as initialSchools, students as initialStudents } from '@/mockData';
import type { Announcement, Role, School, Student, User } from '@/types';

type DesktopPage = 'schools' | 'users' | 'overview' | 'classes' | 'people' | 'schedule' | 'announcements' | 'reports' | 'plans';
type MobilePage = 'attendance' | 'homework' | 'newHomework' | 'history' | 'parentOverview' | 'absence' | 'parentHomework' | 'grades' | 'notifications';

type IconType = typeof LayoutDashboard;

const roleLabel: Record<Role, string> = { superadmin: 'Süper Yönetici', admin: 'Okul Yöneticisi', teacher: 'Öğretmen', parent: 'Veli' };

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-emerald-500 text-white shadow-lg shadow-emerald-200"><Send size={20} className="-rotate-45" /></div>{!compact && <div><div className="text-[17px] font-bold tracking-tight text-slate-900">Okul Pusulası</div><div className="text-[10px] font-medium text-slate-400">Eğitime yön veren platform</div></div>}</div>;
}

function Button({ children, variant = 'primary', onClick, type = 'button', className = '' }: { children: ReactNode; variant?: 'primary' | 'soft' | 'ghost' | 'danger'; onClick?: () => void; type?: 'button' | 'submit'; className?: string }) {
  const styles = { primary: 'bg-emerald-500 text-white shadow-lg shadow-emerald-100 hover:bg-emerald-600', soft: 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100', ghost: 'bg-white text-slate-600 ring-1 ring-slate-200 hover:bg-slate-50', danger: 'bg-rose-50 text-rose-600 hover:bg-rose-100' };
  return <button type={type} onClick={onClick} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 text-sm font-semibold transition ${styles[variant]} ${className}`}>{children}</button>;
}

function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={`rounded-2xl border border-slate-100 bg-white shadow-[0_12px_35px_rgba(29,78,73,.05)] ${className}`}>{children}</div>; }
function Badge({ children, tone = 'green' }: { children: ReactNode; tone?: 'green' | 'amber' | 'blue' | 'rose' | 'slate' }) { const tones = { green: 'bg-emerald-50 text-emerald-700', amber: 'bg-amber-50 text-amber-700', blue: 'bg-sky-50 text-sky-700', rose: 'bg-rose-50 text-rose-700', slate: 'bg-slate-100 text-slate-600' }; return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-bold ${tones[tone]}`}>{children}</span>; }
function Avatar({ initials, tone = 'green' }: { initials: string; tone?: string }) { return <div className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-${tone}-100 text-xs font-bold text-${tone}-700`}>{initials}</div>; }
function IconButton({ children, onClick }: { children: ReactNode; onClick?: () => void }) { return <button onClick={onClick} className="grid h-10 w-10 place-items-center rounded-xl text-slate-500 transition hover:bg-emerald-50 hover:text-emerald-600">{children}</button>; }

function Login({ onLogin }: { onLogin: (user: User) => void }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); const user = accounts.find((item) => item.email === email && password === '123456'); if (user) onLogin(user); else setError('E-posta veya şifre hatalı. Deneme hesaplarından birini kullanabilirsiniz.'); };
  return <main className="soft-grid flex min-h-screen items-center justify-center overflow-hidden px-4 py-8"><div className="absolute -left-20 -top-20 h-72 w-72 rounded-full bg-emerald-100/60 blur-3xl" /><div className="absolute -bottom-24 -right-10 h-80 w-80 rounded-full bg-teal-100/50 blur-3xl" /><div className="relative grid w-full max-w-5xl overflow-hidden rounded-[32px] border border-white bg-white/80 shadow-2xl shadow-emerald-100/60 backdrop-blur lg:grid-cols-[1.1fr_.9fr]"><div className="hidden flex-col justify-between bg-emerald-500 p-12 text-white lg:flex"><div><Logo compact /><p className="mt-14 max-w-sm text-4xl font-bold leading-tight">Eğitimde doğru yönü birlikte bulalım.</p><p className="mt-5 max-w-sm text-sm leading-6 text-emerald-50">Okulunuzun tüm süreçlerini tek, sade ve güvenli bir platformdan yönetin.</p></div><div className="flex items-center gap-2 text-sm text-emerald-50"><ShieldCheck size={18} /> Verileriniz güvende, okulunuz kontrolünüzde.</div></div><div className="p-7 sm:p-12"><div className="mb-10 lg:hidden"><Logo /></div><div className="mb-8"><p className="mb-2 text-sm font-bold text-emerald-600">Hoş geldiniz</p><h1 className="text-3xl font-bold tracking-tight text-slate-900">Hesabınıza giriş yapın</h1><p className="mt-2 text-sm leading-6 text-slate-500">Okul Pusulası hesabınızla tüm süreçlere erişin.</p></div><form onSubmit={submit} className="space-y-5"><label className="block text-sm font-semibold text-slate-700">E-posta<input value={email} onChange={(e) => setEmail(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-4 outline-none transition focus:border-emerald-400 focus:ring-4 focus:ring-emerald-50" placeholder="ornek@okul.com" type="email" required /></label><label className="block text-sm font-semibold text-slate-700">Şifre<input value={password} onChange={(e) => setPassword(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-4 outline-none transition focus:border-emerald-400 focus:ring-4 focus:ring-emerald-50" placeholder="••••••••" type="password" required /></label>{error && <div className="rounded-xl bg-rose-50 px-4 py-3 text-sm font-medium text-rose-700">{error}</div>}<Button type="submit" className="w-full">Giriş Yap <ArrowRight size={17} /></Button></form><div className="mt-8 rounded-2xl bg-slate-50 p-4"><p className="mb-3 text-xs font-bold uppercase tracking-wider text-slate-400">Demo hesapları</p><div className="grid grid-cols-2 gap-2 text-xs text-slate-600"><button onClick={() => { setEmail('super@test.com'); setPassword('123456'); }} className="rounded-lg bg-white p-2 text-left hover:bg-emerald-50">Süper yönetici</button><button onClick={() => { setEmail('mudur@test.com'); setPassword('123456'); }} className="rounded-lg bg-white p-2 text-left hover:bg-emerald-50">Okul yöneticisi</button><button onClick={() => { setEmail('ogretmen@test.com'); setPassword('123456'); }} className="rounded-lg bg-white p-2 text-left hover:bg-emerald-50">Öğretmen</button><button onClick={() => { setEmail('veli@test.com'); setPassword('123456'); }} className="rounded-lg bg-white p-2 text-left hover:bg-emerald-50">Veli</button></div></div></div></div></main>;
}

const superNav: { id: DesktopPage; label: string; icon: IconType }[] = [{ id: 'schools', label: 'Tüm Okullarım', icon: GraduationCap }, { id: 'users', label: 'Kullanıcılar', icon: Users }];
const adminNav: { id: DesktopPage; label: string; icon: IconType }[] = [{ id: 'overview', label: 'Genel Bakış', icon: LayoutDashboard }, { id: 'classes', label: 'Sınıflar', icon: GraduationCap }, { id: 'people', label: 'Kişiler', icon: Users }, { id: 'schedule', label: 'Ders Programı', icon: CalendarDays }, { id: 'announcements', label: 'Duyurular', icon: Megaphone }, { id: 'reports', label: 'Raporlar', icon: BarChart3 }, { id: 'plans', label: 'Çalışma Çizelgesi', icon: ClipboardCheck }];

function Sidebar({ user, page, onNavigate, onLogout }: { user: User; page: DesktopPage; onNavigate: (page: DesktopPage) => void; onLogout: () => void }) {
  const nav = user.role === 'superadmin' ? superNav : adminNav;
  return <aside className="hidden w-64 shrink-0 flex-col border-r border-slate-100 bg-white p-5 lg:flex"><Logo /><div className="mt-10 flex-1 space-y-1">{nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => onNavigate(id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${page === id ? 'bg-emerald-50 text-emerald-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}><Icon size={18} />{label}</button>)}</div><div className="rounded-2xl bg-slate-50 p-3"><div className="flex items-center gap-3"><Avatar initials={user.initials} /><div className="min-w-0"><p className="truncate text-xs font-bold text-slate-800">{user.name}</p><p className="truncate text-[10px] text-slate-400">{roleLabel[user.role]}</p></div></div><button onClick={onLogout} className="mt-4 flex items-center gap-2 text-xs font-semibold text-slate-400 hover:text-rose-600"><LogOut size={14} /> Çıkış yap</button></div></aside>;
}

function Topbar({ title, user, onLogout }: { title: string; user: User; onLogout: () => void }) { return <header className="flex items-center justify-between border-b border-slate-100 bg-white/85 px-5 py-4 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><div className="lg:hidden"><Logo compact /></div><div className="hidden lg:block"><p className="text-xs font-medium text-slate-400">Okul Pusulası / {user.school || 'Platform'}</p><h1 className="text-xl font-bold text-slate-900">{title}</h1></div></div><div className="flex items-center gap-1"><IconButton><Bell size={18} /></IconButton><IconButton><Settings2 size={18} /></IconButton><button onClick={onLogout} className="ml-2 hidden items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-xs font-bold text-slate-600 sm:flex"><Avatar initials={user.initials} /><span>{user.name.split(' ')[0]}</span><ChevronDown size={14} /></button></div></header>; }

function Shell({ user, page, onNavigate, onLogout, children }: { user: User; page: DesktopPage; onNavigate: (page: DesktopPage) => void; onLogout: () => void; children: ReactNode }) { const title = (user.role === 'superadmin' ? superNav : adminNav).find((item) => item.id === page)?.label || 'Genel Bakış'; return <div className="flex min-h-screen bg-[#f6faf9]"><Sidebar user={user} page={page} onNavigate={onNavigate} onLogout={onLogout} /><div className="min-w-0 flex-1"><Topbar title={title} user={user} onLogout={onLogout} /><main className="fade-up mx-auto max-w-[1500px] p-5 sm:p-8">{children}</main></div></div>; }

function SectionHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-bold uppercase tracking-[.18em] text-emerald-600">{eyebrow}</p>}<h2 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{title}</h2>{description && <p className="mt-2 text-sm text-slate-500">{description}</p>}</div>{action}</div>; }

function Stat({ label, value, trend, icon: Icon, tone = 'green' }: { label: string; value: string; trend: string; icon: IconType; tone?: string }) { return <Card className="p-5"><div className="flex items-start justify-between"><div className={`grid h-11 w-11 place-items-center rounded-2xl bg-${tone}-50 text-${tone}-600`}><Icon size={20} /></div><Badge tone="green">{trend}</Badge></div><p className="mt-5 text-sm font-medium text-slate-500">{label}</p><p className="mt-1 text-2xl font-bold text-slate-900">{value}</p></Card>; }

function SuperAdmin({ user, page, setPage, onLogout }: { user: User; page: DesktopPage; setPage: (page: DesktopPage) => void; onLogout: () => void }) {
  const [schools, setSchools] = useState(initialSchools);
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState<School | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [tab, setTab] = useState<'general' | 'manager' | 'plan'>('general');
  const filtered = schools.filter((school) => school.name.toLowerCase().includes(search.toLowerCase()) || school.city.toLowerCase().includes(search.toLowerCase()));
  const addSchool = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const item: School = { id: `s${Date.now()}`, name: String(data.get('name')), city: String(data.get('city')), students: 0, classes: 0, teachers: 0, parents: 0, status: 'Deneme', principal: 'Atanmadı', plan: 'Deneme' }; setSchools((current) => [item, ...current]); setShowModal(false); };
  return <Shell user={user} page={page} onNavigate={setPage} onLogout={onLogout}>{page === 'users' ? <UsersPage /> : selected ? <SchoolDetail school={selected} tab={tab} setTab={setTab} onBack={() => setSelected(null)} /> : <><SectionHeading eyebrow="Platform yönetimi" title="Tüm Okullarım" description="Sisteminize bağlı okulları tek bir yerden yönetin." action={<Button onClick={() => setShowModal(true)}><Plus size={17} /> Yeni Okul Ekle</Button>} /><div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-3.5 text-slate-400" size={17} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Okul veya şehir ara..." className="h-11 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-4 text-sm outline-none focus:border-emerald-400" /></div><div className="flex items-center gap-2"><Badge tone="green">{schools.length} okul</Badge><Button variant="ghost"><Settings2 size={16} /> Filtrele</Button></div></div><Card className="overflow-hidden"><div className="hidden overflow-x-auto md:block"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-xs uppercase tracking-wider text-slate-400"><tr>{['Okul Adı', 'Şehir', 'Öğrenci', 'Sınıf', 'Öğretmen', 'Veli', 'Durum', ''].map((item) => <th key={item} className="px-5 py-4 font-bold">{item}</th>)}</tr></thead><tbody>{filtered.map((school) => <tr key={school.id} onClick={() => setSelected(school)} className="cursor-pointer border-b border-slate-50 transition hover:bg-emerald-50/40"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><GraduationCap size={17} /></div><div><p className="font-bold text-slate-800">{school.name}</p><p className="text-xs text-slate-400">{school.plan} plan</p></div></div></td><td className="px-5 py-4 text-slate-500">{school.city}</td><td className="px-5 py-4 font-semibold text-slate-700">{school.students.toLocaleString('tr-TR')}</td><td className="px-5 py-4 text-slate-500">{school.classes}</td><td className="px-5 py-4 text-slate-500">{school.teachers}</td><td className="px-5 py-4 text-slate-500">{school.parents.toLocaleString('tr-TR')}</td><td className="px-5 py-4"><Badge tone={school.status === 'Aktif' ? 'green' : 'amber'}>{school.status}</Badge></td><td className="px-5 py-4 text-right"><ChevronRight size={17} className="text-slate-300" /></td></tr>)}</tbody></table></div><div className="divide-y divide-slate-50 md:hidden">{filtered.map((school) => <button key={school.id} onClick={() => setSelected(school)} className="flex w-full items-center gap-3 p-4 text-left"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><GraduationCap size={18} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-800">{school.name}</p><p className="mt-1 text-xs text-slate-400">{school.city} · {school.students} öğrenci</p></div><Badge tone={school.status === 'Aktif' ? 'green' : 'amber'}>{school.status}</Badge></button>)}</div>{filtered.length === 0 && <EmptyState label="Aramanızla eşleşen okul bulunamadı." />}</Card></>}{showModal && <Modal title="Yeni okul ekle" onClose={() => setShowModal(false)}><form onSubmit={addSchool} className="space-y-4"><label className="block text-sm font-semibold text-slate-700">Okul adı<input name="name" required className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 outline-none focus:border-emerald-400" placeholder="Örn. Cumhuriyet Lisesi" /></label><label className="block text-sm font-semibold text-slate-700">Şehir<input name="city" required className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 outline-none focus:border-emerald-400" placeholder="İstanbul" /></label><Button type="submit" className="w-full">Okulu Ekle</Button></form></Modal>}</Shell>;
}

function SchoolDetail({ school, tab, setTab, onBack }: { school: School; tab: 'general' | 'manager' | 'plan'; setTab: (tab: 'general' | 'manager' | 'plan') => void; onBack: () => void }) { return <><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-emerald-600"><ChevronLeft size={16} /> Okul listesine dön</button><SectionHeading title={school.name} description={`${school.city} · ${school.plan} plan`} action={<Badge tone="green">{school.status}</Badge>} /><Card><div className="flex gap-1 border-b border-slate-100 p-2">{[['general', 'Genel Bilgiler'], ['manager', 'Yönetici'], ['plan', 'Ödeme Planı']].map(([value, label]) => <button key={value} onClick={() => setTab(value as 'general' | 'manager' | 'plan')} className={`rounded-xl px-4 py-2.5 text-sm font-semibold ${tab === value ? 'bg-emerald-50 text-emerald-700' : 'text-slate-400 hover:text-slate-700'}`}>{label}</button>)}</div><div className="p-6">{tab === 'general' && <div className="grid gap-4 sm:grid-cols-3"><Detail label="Öğrenci" value={school.students.toLocaleString('tr-TR')} /><Detail label="Sınıf" value={String(school.classes)} /><Detail label="Öğretmen" value={String(school.teachers)} /><Detail label="Veli" value={school.parents.toLocaleString('tr-TR')} /><Detail label="Şehir" value={school.city} /><Detail label="Durum" value={school.status} /></div>}{tab === 'manager' && <div className="flex items-center gap-4"><Avatar initials={school.principal.split(' ').map((n) => n[0]).join('')} tone="blue" /><div><p className="font-bold text-slate-900">{school.principal}</p><p className="text-sm text-slate-400">Okul yöneticisi</p></div><Button variant="ghost" className="ml-auto">Düzenle</Button></div>}{tab === 'plan' && <div className="flex flex-col justify-between gap-4 rounded-2xl bg-emerald-50 p-5 sm:flex-row sm:items-center"><div><p className="text-sm font-bold text-emerald-800">{school.plan} Plan</p><p className="mt-1 text-sm text-emerald-700/70">Aylık faturalandırma · Son ödeme 16.09.2026</p></div><Badge tone="green">Ödendi</Badge></div>}</div></Card></>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs text-slate-400">{label}</p><p className="mt-2 font-bold text-slate-800">{value}</p></div>; }
function UsersPage() { const [query, setQuery] = useState(''); const allUsers = [...accounts, { id: 'u5', name: 'Okan Demir', email: 'okan@okul.com', role: 'teacher' as Role, title: 'Fen Bilimleri', school: 'Atatürk İlkokulu', initials: 'OD' }]; const filtered = allUsers.filter((u) => `${u.name} ${u.email}`.toLowerCase().includes(query.toLowerCase())); return <><SectionHeading eyebrow="Platform yönetimi" title="Kullanıcılar" description="Tüm okullardaki kullanıcıları görüntüleyin ve yönetin." /><div className="mb-5 flex max-w-md items-center gap-2"><div className="relative flex-1"><Search className="absolute left-3 top-3.5 text-slate-400" size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Kullanıcı ara..." className="h-11 w-full rounded-xl border border-slate-200 pl-10 pr-4 text-sm outline-none focus:border-emerald-400" /></div><Button variant="ghost"><Settings2 size={16} /> Filtre</Button></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-xs uppercase tracking-wider text-slate-400"><tr>{['Kullanıcı', 'Rol', 'Okul', 'Durum', ''].map((item) => <th key={item} className="px-5 py-4">{item}</th>)}</tr></thead><tbody>{filtered.map((item) => <tr key={item.id} className="border-b border-slate-50"><td className="px-5 py-4"><div className="flex items-center gap-3"><Avatar initials={item.initials} /><div><p className="font-bold text-slate-800">{item.name}</p><p className="text-xs text-slate-400">{item.email}</p></div></div></td><td className="px-5 py-4"><Badge tone={item.role === 'superadmin' ? 'rose' : item.role === 'admin' ? 'amber' : item.role === 'teacher' ? 'blue' : 'green'}>{roleLabel[item.role]}</Badge></td><td className="px-5 py-4 text-slate-500">{item.school || 'Tüm okullar'}</td><td className="px-5 py-4"><Badge>Aktif</Badge></td><td className="px-5 py-4 text-right"><Button variant="ghost" className="min-h-8 px-3 text-xs">Görüntüle</Button></td></tr>)}</tbody></table></div></Card></>; }

function Admin({ user, page, setPage, onLogout }: { user: User; page: DesktopPage; setPage: (page: DesktopPage) => void; onLogout: () => void }) { const [students] = useState(initialStudents); const [announcements, setAnnouncements] = useState(initialAnnouncements); return <Shell user={user} page={page} onNavigate={setPage} onLogout={onLogout}>{page === 'overview' && <AdminOverview setPage={setPage} />}{page === 'classes' && <ClassesPage />}{page === 'people' && <PeoplePage students={students} />}{page === 'schedule' && <SchedulePage />}{page === 'announcements' && <AnnouncementsPage announcements={announcements} setAnnouncements={setAnnouncements} />}{page === 'reports' && <ReportsPage students={students} />}{page === 'plans' && <PlansPage students={students} />}</Shell>; }
function AdminOverview({ setPage }: { setPage: (page: DesktopPage) => void }) { return <><div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 text-sm font-semibold text-emerald-600">Günaydın, Mehmet</p><h2 className="text-3xl font-bold tracking-tight text-slate-900">Okulunuz bugün nasıl?</h2><p className="mt-2 text-sm text-slate-500">Nilüfer Anadolu Lisesi için güncel özet.</p></div><Button variant="soft"><CalendarDays size={17} /> 16 Eylül 2026</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Öğrenci" value="1.240" trend="%8.2" icon={GraduationCap} /><Stat label="Sınıf" value="42" trend="%4.1" icon={BookOpen} tone="blue" /><Stat label="Öğretmen" value="68" trend="%2.4" icon={Users} tone="amber" /><Stat label="Veli" value="1.050" trend="%6.8" icon={UserRound} tone="sky" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Card className="p-6"><div className="flex items-center justify-between"><div><p className="text-lg font-bold text-slate-900">Son Aktiviteler</p><p className="mt-1 text-sm text-slate-400">Okulunuzdaki son hareketler</p></div><Button variant="ghost" className="min-h-9 px-3 text-xs">Tümünü gör</Button></div><div className="mt-5 space-y-4">{[['AY', 'Ayşe Yılmaz', '9A sınıfına yeni ödev ekledi', '5 dk önce', 'green'], ['MD', 'Mehmet Demir', 'Veli toplantısı duyurusu gönderdi', '32 dk önce', 'blue'], ['EA', 'Elif Arslan', '10A sınıfına kaydoldu', '1 saat önce', 'amber']].map(([initials, name, text, time, tone]) => <div key={text} className="flex items-center gap-3"><Avatar initials={initials} tone={tone} /><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-slate-700"><span className="font-bold text-slate-900">{name}</span> {text}</p><p className="mt-0.5 text-xs text-slate-400">{time}</p></div></div>)}</div></Card><Card className="p-6"><p className="text-lg font-bold text-slate-900">Hızlı İşlemler</p><p className="mt-1 text-sm text-slate-400">Sık kullandığınız işlemler</p><div className="mt-5 space-y-2"><Button onClick={() => setPage('announcements')} variant="soft" className="w-full justify-start"><Megaphone size={17} /> Duyuru oluştur</Button><Button onClick={() => setPage('people')} variant="ghost" className="w-full justify-start"><Users size={17} /> Yeni kişi ekle</Button><Button onClick={() => setPage('plans')} variant="ghost" className="w-full justify-start"><ClipboardCheck size={17} /> Çalışma planı hazırla</Button></div></Card></div></>; }
function ClassesPage() { const classes = [['9A', 'Ayşe Yılmaz', '32', 'Matematik'], ['9B', 'Zeynep Çelik', '28', 'Türkçe'], ['10A', 'Mehmet Kaya', '30', 'Fizik'], ['10B', 'Selin Arslan', '27', 'Kimya'], ['11A', 'Ali Demir', '26', 'Biyoloji'], ['12A', 'Elif Yılmaz', '24', 'Edebiyat']]; return <><SectionHeading eyebrow="Okul yönetimi" title="Sınıflar" description="Sınıfları, öğretmenleri ve öğrenci sayılarını yönetin." action={<Button><Plus size={17} /> Yeni Sınıf</Button>} /><Card className="overflow-hidden"><div className="hidden md:block"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-xs uppercase tracking-wider text-slate-400"><tr>{['Sınıf', 'Sınıf öğretmeni', 'Öğrenci', 'Ders', ''].map((item) => <th key={item} className="px-5 py-4">{item}</th>)}</tr></thead><tbody>{classes.map(([name, teacher, count, subject]) => <tr key={name} className="border-b border-slate-50"><td className="px-5 py-4 font-bold text-slate-800">{name}</td><td className="px-5 py-4 text-slate-500">{teacher}</td><td className="px-5 py-4 text-slate-500">{count} öğrenci</td><td className="px-5 py-4"><Badge tone="blue">{subject}</Badge></td><td className="px-5 py-4 text-right"><ChevronRight size={17} className="text-slate-300" /></td></tr>)}</tbody></table></div><div className="divide-y divide-slate-50 md:hidden">{classes.map(([name, teacher, count, subject]) => <div key={name} className="flex items-center gap-3 p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-sm font-bold text-emerald-700">{name}</div><div className="flex-1"><p className="font-bold text-slate-800">{teacher}</p><p className="text-xs text-slate-400">{count} öğrenci · {subject}</p></div><ChevronRight size={16} className="text-slate-300" /></div>)}</div></Card></>; }
function PeoplePage({ students }: { students: Student[] }) { const [tab, setTab] = useState('Öğrenciler'); return <><SectionHeading eyebrow="Okul yönetimi" title="Kişiler" description="Okul topluluğunuzdaki tüm kişileri yönetin." action={<Button><Plus size={17} /> Yeni Öğrenci</Button>} /><Tabs items={['Öğrenciler', 'Öğretmenler', 'Veliler']} active={tab} onChange={setTab} /><Card className="mt-4 overflow-hidden"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 bg-slate-50/70 text-xs uppercase tracking-wider text-slate-400"><tr>{['Ad Soyad', 'Sınıf', 'Veli', 'İşlemler'].map((item) => <th key={item} className="px-5 py-4">{item}</th>)}</tr></thead><tbody>{tab === 'Öğrenciler' ? students.map((student) => <tr key={student.id} className="border-b border-slate-50"><td className="px-5 py-4"><div className="flex items-center gap-3"><Avatar initials={student.avatar} /><span className="font-bold text-slate-800">{student.name}</span></div></td><td className="px-5 py-4"><Badge tone="blue">{student.className}</Badge></td><td className="px-5 py-4 text-slate-500">{student.parent}</td><td className="px-5 py-4 text-right"><Button variant="ghost" className="min-h-8 px-3 text-xs">Düzenle</Button></td></tr>) : Array.from({ length: 4 }, (_, index) => <tr key={index} className="border-b border-slate-50"><td className="px-5 py-4"><div className="flex items-center gap-3"><Avatar initials={['MK', 'SA', 'BC', 'EY'][index]} /><span className="font-bold text-slate-800">{['Mehmet Kaya', 'Selin Arslan', 'Bora Çetin', 'Ece Yılmaz'][index]}</span></div></td><td className="px-5 py-4 text-slate-500">{tab === 'Öğretmenler' ? 'Öğretmen' : 'Veli'}</td><td className="px-5 py-4 text-slate-500">{tab === 'Veliler' ? '1 öğrenci' : '—'}</td><td className="px-5 py-4 text-right"><Button variant="ghost" className="min-h-8 px-3 text-xs">Görüntüle</Button></td></tr>)}</tbody></table></Card></>; }
function Tabs({ items, active, onChange }: { items: string[]; active: string; onChange: (item: string) => void }) { return <div className="flex w-fit max-w-full gap-1 overflow-auto rounded-xl bg-slate-100 p-1">{items.map((item) => <button key={item} onClick={() => onChange(item)} className={`whitespace-nowrap rounded-lg px-4 py-2 text-sm font-semibold ${active === item ? 'bg-white text-emerald-700 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>{item}</button>)}</div>; }
function SchedulePage() { const days = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma']; return <><SectionHeading eyebrow="Okul yönetimi" title="Ders Programı" description="Haftalık ders programınızı düzenleyin." action={<Button variant="soft"><CalendarDays size={17} /> 16–22 Eylül 2026</Button>} /><Card className="overflow-x-auto p-4"><div className="grid min-w-[720px] grid-cols-[80px_repeat(5,1fr)] gap-2"><div /><div className="p-3 text-center text-xs font-bold text-slate-400">{days[0]}</div><div className="p-3 text-center text-xs font-bold text-slate-400">{days[1]}</div><div className="p-3 text-center text-xs font-bold text-slate-400">{days[2]}</div><div className="p-3 text-center text-xs font-bold text-slate-400">{days[3]}</div><div className="p-3 text-center text-xs font-bold text-slate-400">{days[4]}</div>{schedule.map((item, index) => <div key={item.time} className="contents"><div className="flex items-center justify-center text-xs font-bold text-slate-400">{item.time}</div>{days.map((day, dayIndex) => <button key={day} className={`min-h-20 rounded-xl border p-3 text-left transition hover:-translate-y-0.5 hover:shadow-md ${dayIndex === index % 5 ? `border-${item.color}-200 bg-${item.color}-50` : 'border-slate-100 bg-slate-50/50'}`}><p className="text-xs font-bold text-slate-800">{dayIndex === index % 5 ? item.subject : ['İngilizce', 'Tarih', 'Biyoloji', 'Felsefe'][dayIndex % 4]}</p><p className="mt-1 text-[10px] text-slate-400">{dayIndex === index % 5 ? item.teacher : 'Ders saati'}</p></button>)}</div>)}</div></Card></>; }
function AnnouncementsPage({ announcements, setAnnouncements }: { announcements: Announcement[]; setAnnouncements: (items: Announcement[]) => void }) { const [title, setTitle] = useState(''); const [message, setMessage] = useState(''); const submit = (event: FormEvent) => { event.preventDefault(); if (!title.trim() || !message.trim()) return; setAnnouncements([{ id: `a${Date.now()}`, title, audience: 'Tüm Okul', date: 'Bugün', color: 'emerald' }, ...announcements]); setTitle(''); setMessage(''); }; return <><SectionHeading eyebrow="Okul yönetimi" title="Duyurular" description="Velilere ve öğretmenlere güncel duyurular gönderin." /><div className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Card className="p-6"><p className="text-lg font-bold text-slate-900">Yeni duyuru</p><form onSubmit={submit} className="mt-5 space-y-4"><input value={title} onChange={(e) => setTitle(e.target.value)} required className="h-11 w-full rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-emerald-400" placeholder="Duyuru başlığı" /><textarea value={message} onChange={(e) => setMessage(e.target.value)} required className="h-32 w-full resize-none rounded-xl border border-slate-200 p-3 text-sm outline-none focus:border-emerald-400" placeholder="Duyuru mesajınızı buraya yazın..." /><div className="flex gap-2"><Button variant="soft">Hedef kitle: Herkes <ChevronDown size={14} /></Button><Button type="submit" className="flex-1"><Send size={16} /> Duyuruyu Gönder</Button></div></form></Card><Card className="p-6"><div className="flex items-center justify-between"><div><p className="text-lg font-bold text-slate-900">Gönderilen duyurular</p><p className="mt-1 text-sm text-slate-400">Son paylaşımlarınız</p></div><Badge>{announcements.length} duyuru</Badge></div><div className="mt-5 space-y-3">{announcements.map((item) => <div key={item.id} className="flex items-center gap-3 rounded-2xl border border-slate-100 p-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><Megaphone size={17} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-800">{item.title}</p><p className="mt-1 text-xs text-slate-400">{item.date} · {item.audience}</p></div><Badge tone="green">Gönderildi</Badge></div>)}{announcements.length === 0 && <EmptyState label="Henüz duyuru bulunmuyor." />}</div></Card></div></>; }
function ReportsPage({ students }: { students: Student[] }) { const [tab, setTab] = useState('Deneme Sonuçları'); void students; return <><SectionHeading eyebrow="Okul yönetimi" title="Raporlar" description="Öğrenci gelişimini ve okul performansını izleyin." /><Tabs items={['Deneme Sonuçları', 'Koçluk Notları']} active={tab} onChange={setTab} /><Card className="mt-4 overflow-hidden p-5">{tab === 'Deneme Sonuçları' ? <><div className="mb-5 flex flex-wrap gap-2"><Button variant="ghost">9A <ChevronDown size={14} /></Button><Button variant="ghost">1. Deneme <ChevronDown size={14} /></Button><Button variant="ghost">16.09.2026 <CalendarDays size={14} /></Button></div><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase tracking-wider text-slate-400"><tr><th className="py-3">Öğrenci</th><th className="py-3">Net</th><th className="py-3">Puan</th><th className="py-3">Durum</th></tr></thead><tbody>{students.slice(0, 4).map((student, index) => <tr key={student.id} className="border-b border-slate-50"><td className="py-4 font-bold text-slate-800">{student.name}</td><td className="py-4 text-slate-500">{32 - index}</td><td className="py-4 font-bold text-slate-700">{412 - index * 16}</td><td className="py-4"><Badge tone={index === 1 ? 'amber' : 'green'}>{index === 1 ? 'Geliştirilmeli' : 'İyi'}</Badge></td></tr>)}</tbody></table></> : <div className="space-y-3">{['Düzenli çalışmaya devam etmeli.', 'Deneme analizleri velisiyle paylaşıldı.', 'Matematikte konu tekrarı önerildi.'].map((note, index) => <div key={note} className="flex items-center gap-3 rounded-xl bg-slate-50 p-4"><Avatar initials={students[index].avatar} /><div><p className="text-sm font-bold text-slate-800">{students[index].name}</p><p className="mt-1 text-xs text-slate-500">{note}</p></div></div>)}</div>}</Card></>; }
function PlansPage({ students }: { students: Student[] }) { void students; const [checked, setChecked] = useState<number[]>([0, 1, 3, 5, 8]); return <><SectionHeading eyebrow="Okul yönetimi" title="Çalışma Çizelgesi" description="Öğrencileriniz için haftalık çalışma planı oluşturun." action={<Button><Plus size={17} /> Plan Ekle</Button>} /><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Card className="overflow-hidden p-5"><div className="mb-4 flex items-center justify-between"><div><p className="font-bold text-slate-900">10A sınıfı</p><p className="text-xs text-slate-400">16–22 Eylül 2026</p></div><Button variant="soft"><ChevronLeft size={15} /> <ChevronRight size={15} /></Button></div><div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left text-xs"><thead><tr className="text-slate-400"><th className="pb-3">Ders</th>{['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'].map((day) => <th key={day} className="pb-3 text-center">{day}</th>)}</tr></thead><tbody>{['Matematik', 'Türkçe', 'Fizik', 'Kimya'].map((subject, row) => <tr key={subject} className="border-t border-slate-50"><td className="py-4 font-bold text-slate-700">{subject}</td>{Array.from({ length: 7 }, (_, index) => { const key = row * 7 + index; return <td key={key} className="py-4 text-center"><button onClick={() => setChecked((current) => current.includes(key) ? current.filter((item) => item !== key) : [...current, key])} className={`mx-auto grid h-6 w-6 place-items-center rounded-md border ${checked.includes(key) ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-200 text-transparent'}`}><Check size={14} /></button></td>; })}</tr>)}</tbody></table></div></Card><Card className="p-6"><div className="flex items-start justify-between"><div><p className="font-bold text-slate-900">Mehmet Kaya</p><p className="mt-1 text-xs text-slate-400">10A · Bu haftanın planı</p></div><Avatar initials="MK" tone="blue" /></div><div className="mt-6 space-y-4"><div className="flex justify-between text-sm"><span className="text-slate-500">Tamamlanma</span><span className="font-bold text-emerald-600">%64</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-2 w-2/3 rounded-full bg-emerald-500" /></div><p className="text-sm leading-6 text-slate-500">Düzenli çalışmaya devam ediyor. Matematik tekrarları güçlü ilerliyor.</p><Button className="w-full">Planı Kaydet</Button></div></Card></div></>; }

function MobileShell({ user, page, setPage, onLogout, children }: { user: User; page: MobilePage; setPage: (page: MobilePage) => void; onLogout: () => void; children: ReactNode }) { const teacherItems: { id: MobilePage; label: string; icon: IconType }[] = [{ id: 'attendance', label: 'Yoklama', icon: ClipboardCheck }, { id: 'homework', label: 'Ödevler', icon: BookOpen }, { id: 'newHomework', label: 'Yeni Ödev', icon: Plus }, { id: 'history', label: 'Geçmiş', icon: History }]; const parentItems: { id: MobilePage; label: string; icon: IconType }[] = [{ id: 'parentOverview', label: 'Genel Bakış', icon: Home }, { id: 'absence', label: 'Devamsızlık', icon: Clock3 }, { id: 'parentHomework', label: 'Ödev Takibi', icon: FileCheck2 }, { id: 'grades', label: 'Deneme & Notlar', icon: BarChart3 }, { id: 'notifications', label: 'Bildirimler', icon: Bell }]; const items = user.role === 'teacher' ? teacherItems : parentItems; const title = items.find((item) => item.id === page)?.label || ''; return <div className="mx-auto min-h-screen max-w-lg bg-[#f6faf9] shadow-2xl shadow-slate-200/50"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-100 bg-white/90 px-5 py-4 backdrop-blur"><div className="flex items-center gap-3"><Logo compact /><div><p className="text-[10px] font-bold text-emerald-600">{user.school}</p><h1 className="text-sm font-bold text-slate-900">{title}</h1></div></div><div className="flex items-center gap-1"><IconButton><Bell size={18} /></IconButton><button onClick={onLogout} className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-50 text-xs font-bold text-emerald-700">{user.initials}</button></div></header><main className="fade-up min-h-[calc(100vh-150px)] p-5 pb-28">{children}</main><nav className="fixed bottom-0 left-1/2 z-20 flex w-full max-w-lg -translate-x-1/2 justify-around border-t border-slate-100 bg-white/95 px-2 py-2 shadow-[0_-10px_30px_rgba(29,78,73,.08)] backdrop-blur">{items.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setPage(id)} className={`flex min-w-[58px] flex-col items-center gap-1 rounded-xl px-2 py-2 text-[10px] font-bold ${page === id ? 'bg-emerald-50 text-emerald-600' : 'text-slate-400'}`}><Icon size={18} /><span>{label}</span></button>)}</nav></div>; }

function Teacher({ user, page, setPage, onLogout }: { user: User; page: MobilePage; setPage: (page: MobilePage) => void; onLogout: () => void }) { const [students, setStudents] = useState(initialStudents); const [homeworks, setHomeworks] = useState(homework); return <MobileShell user={user} page={page} setPage={setPage} onLogout={onLogout}>{page === 'attendance' && <TeacherAttendance students={students} setStudents={setStudents} />}{page === 'homework' && <TeacherHomework homeworks={homeworks} />}{page === 'newHomework' && <NewHomework onCreate={(title) => { setHomeworks([{ id: `h${Date.now()}`, title, subject: 'Matematik', due: '25 Eylül', done: 0, total: students.length, status: 'Aktif' }, ...homeworks]); setPage('homework'); }} />}{page === 'history' && <HistoryPage />}</MobileShell>; }
function TeacherAttendance({ students, setStudents }: { students: Student[]; setStudents: (students: Student[]) => void }) { const toggle = (id: string) => setStudents(students.map((student) => student.id === id ? { ...student, attendance: student.attendance === 'present' ? 'absent' : 'present' } : student)); return <><div className="mb-6"><p className="text-xs font-bold uppercase tracking-wider text-emerald-600">16 Eylül 2026 · 1. Ders</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Yoklama</h2><p className="mt-1 text-sm text-slate-500">9A · Matematik</p></div><div className="mb-4 rounded-2xl border border-emerald-400/20 bg-emerald-500 p-4 text-white shadow-[0_12px_35px_rgba(29,78,73,.12)]"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-emerald-100">Aktif ders</p><p className="mt-2 text-base font-bold">08:00 – 08:40 · Matematik</p></div><div className="grid h-10 w-10 place-items-center rounded-xl bg-white/20"><Clock3 size={19} /></div></div></div><div className="mb-4 flex items-center justify-between"><p className="font-bold text-slate-900">Öğrenciler <span className="text-slate-400">({students.length})</span></p><Button variant="soft" onClick={() => setStudents(students.map((student) => ({ ...student, attendance: 'present' })))}><Check size={15} /> Herkes geldi</Button></div><div className="space-y-2">{students.map((student) => <Card key={student.id} className="flex items-center gap-3 p-3"><Avatar initials={student.avatar} /><div className="min-w-0 flex-1"><p className="text-sm font-bold text-slate-800">{student.name}</p><p className="text-xs text-slate-400">{student.className}</p></div><button onClick={() => toggle(student.id)} className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-2 text-xs font-bold ${student.attendance === 'present' ? 'bg-emerald-50 text-emerald-700' : student.attendance === 'late' ? 'bg-amber-50 text-amber-700' : 'bg-rose-50 text-rose-700'}`}>{student.attendance === 'present' ? <CheckCircle2 size={14} /> : <XCircle size={14} />}{student.attendance === 'present' ? 'Geldi' : student.attendance === 'late' ? 'Geç' : 'Gelmedi'}</button></Card>)}</div><Button className="mt-5 w-full">Yoklamayı Kaydet</Button></>; }
function TeacherHomework({ homeworks: items }: { homeworks: typeof homework }) { return <><div className="mb-6"><p className="text-xs font-bold uppercase tracking-wider text-emerald-600">Sınıflarınız</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Ödev Kontrolü</h2><p className="mt-1 text-sm text-slate-500">Gönderdiğiniz ödevleri takip edin.</p></div><select className="mb-4 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700"><option>9A Sınıfı</option><option>10B Sınıfı</option></select><div className="space-y-3">{items.map((item) => <Card key={item.id} className="p-4"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><BookOpen size={18} /></div><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><p className="font-bold text-slate-800">{item.title}</p><Badge tone={item.status === 'Tamamlandı' ? 'green' : 'blue'}>{item.status}</Badge></div><p className="mt-1 text-xs text-slate-400">{item.subject} · Son teslim {item.due}</p><div className="mt-4 flex items-center gap-3"><div className="h-2 flex-1 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-emerald-500" style={{ width: `${(item.done / item.total) * 100}%` }} /></div><span className="text-xs font-bold text-slate-500">{item.done}/{item.total}</span></div></div></div></Card>)}</div></>; }
function NewHomework({ onCreate }: { onCreate: (title: string) => void }) { const [title, setTitle] = useState(''); const submit = (event: FormEvent) => { event.preventDefault(); if (title.trim()) onCreate(title); }; return <><div className="mb-6"><p className="text-xs font-bold uppercase tracking-wider text-emerald-600">Yeni çalışma</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Yeni Ödev</h2><p className="mt-1 text-sm text-slate-500">Sınıfınız için hızlıca ödev oluşturun.</p></div><Card className="p-5"><form onSubmit={submit} className="space-y-4"><label className="block text-sm font-semibold text-slate-700">Ders<select className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option>Matematik</option><option>Fizik</option><option>Türkçe</option></select></label><label className="block text-sm font-semibold text-slate-700">Başlık<input value={title} onChange={(e) => setTitle(e.target.value)} required className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-emerald-400" placeholder="Ödev başlığı" /></label><label className="block text-sm font-semibold text-slate-700">Son teslim tarihi<input type="date" defaultValue="2026-09-25" className="mt-2 h-11 w-full rounded-xl border border-slate-200 px-3 text-sm" /></label><Button type="submit" className="w-full"><Send size={16} /> Ödevi Oluştur</Button></form></Card></>; }
function HistoryPage() { const [tab, setTab] = useState('Yoklama'); return <><div className="mb-6"><p className="text-xs font-bold uppercase tracking-wider text-emerald-600">Geçmiş kayıtlar</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Geçmiş</h2><p className="mt-1 text-sm text-slate-500">Yaptığınız işlemlere göz atın.</p></div><Tabs items={['Yoklama', 'Ödev']} active={tab} onChange={setTab} /><div className="mt-4 space-y-3">{(tab === 'Yoklama' ? ['16 Eyl 2026 · 9A Matematik', '15 Eyl 2026 · 10B Fizik', '14 Eyl 2026 · 9A Matematik'] : ['Denklemler ve Eşitsizlikler', 'Kuvvet ve Hareket', 'Paragraf Çalışması']).map((item, index) => <Card key={item} className="flex items-center gap-3 p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-600">{tab === 'Yoklama' ? <ClipboardCheck size={18} /> : <BookOpen size={18} />}</div><div className="flex-1"><p className="text-sm font-bold text-slate-800">{item}</p><p className="mt-1 text-xs text-slate-400">{tab === 'Yoklama' ? `${24 - index * 2} öğrenci · ${index === 0 ? 'Bugün' : 'Tamamlandı'}` : `${index + 1}. sınıf · ${16 + index * 2} teslim`}</p></div><ChevronRight size={16} className="text-slate-300" /></Card>)}</div></>; }

function Parent({ user, page, setPage, onLogout }: { user: User; page: MobilePage; setPage: (page: MobilePage) => void; onLogout: () => void }) { return <MobileShell user={user} page={page} setPage={setPage} onLogout={onLogout}>{page === 'parentOverview' && <ParentOverview setPage={setPage} />}{page === 'absence' && <ParentAbsence />}{page === 'parentHomework' && <ParentHomework />}{page === 'grades' && <ParentGrades />}{page === 'notifications' && <Notifications />}</MobileShell>; }
function ParentOverview({ setPage }: { setPage: (page: MobilePage) => void }) { return <><div className="mb-6 flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-emerald-600">Günaydın, Fatma</p><h2 className="mt-2 text-2xl font-bold text-slate-900">Merhaba, Fatma Hanım</h2><p className="mt-1 text-sm text-slate-500">Ahmet'in güncel durumu burada.</p></div><Avatar initials="AY" /></div><div className="mb-4 rounded-2xl border border-emerald-400/20 bg-emerald-500 p-5 text-white shadow-[0_12px_35px_rgba(29,78,73,.12)]"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-emerald-100">Ahmet Yılmaz</p><p className="mt-2 text-xl font-bold">9A · Matematik</p><p className="mt-3 text-xs font-medium text-emerald-100">Bugünkü ders programı</p></div><div className="grid h-12 w-12 place-items-center rounded-2xl bg-white/15"><GraduationCap size={24} /></div></div><div className="mt-5 grid grid-cols-3 gap-2 text-center text-xs"><div className="rounded-xl bg-white/15 p-2.5"><p className="text-base font-bold">%92</p><p className="mt-1 font-medium text-emerald-100">Devam</p></div><div className="rounded-xl bg-white/15 p-2.5"><p className="text-base font-bold">2</p><p className="mt-1 font-medium text-emerald-100">Ödev</p></div><div className="rounded-xl bg-white/15 p-2.5"><p className="text-base font-bold">86</p><p className="mt-1 font-medium text-emerald-100">Ortalama</p></div></div></div><div className="grid grid-cols-2 gap-3"><button onClick={() => setPage('absence')} className="rounded-2xl border border-slate-100 bg-white p-4 text-left shadow-sm"><div className="grid h-9 w-9 place-items-center rounded-xl bg-rose-50 text-rose-600"><Clock3 size={17} /></div><p className="mt-4 text-sm font-bold text-slate-800">Devamsızlık</p><p className="mt-1 text-xs text-slate-400">2 gün raporlu</p></button><button onClick={() => setPage('parentHomework')} className="rounded-2xl border border-slate-100 bg-white p-4 text-left shadow-sm"><div className="grid h-9 w-9 place-items-center rounded-xl bg-amber-50 text-amber-600"><BookOpen size={17} /></div><p className="mt-4 text-sm font-bold text-slate-800">Ödevler</p><p className="mt-1 text-xs text-slate-400">2 bekliyor</p></button></div><Card className="mt-4 p-5"><div className="flex items-center justify-between"><p className="font-bold text-slate-900">Son duyurular</p><button onClick={() => setPage('notifications')} className="text-xs font-bold text-emerald-600">Tümünü gör</button></div><div className="mt-4 space-y-3">{initialAnnouncements.slice(0, 2).map((item) => <div key={item.id} className="flex gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-50 text-emerald-600"><Megaphone size={16} /></div><div><p className="text-sm font-bold text-slate-800">{item.title}</p><p className="mt-1 text-xs text-slate-400">{item.date}</p></div></div>)}</div></Card></>; }
function ParentAbsence() { return <><SectionHeading eyebrow="Ahmet Yılmaz · 9A" title="Devamsızlık" description="Dönem içindeki devam durumunu takip edin." /><Card className="mb-4 p-5"><div className="flex items-end justify-between"><div><p className="text-sm text-slate-500">Toplam devamsızlık</p><p className="mt-1 text-3xl font-bold text-slate-900">2 gün</p></div><Badge tone="green">Düzenli</Badge></div><div className="mt-5 h-2 rounded-full bg-slate-100"><div className="h-2 w-[8%] rounded-full bg-emerald-500" /></div></Card><div className="space-y-3">{[['16 Eylül 2026', 'Matematik', 'Var', 'green'], ['14 Eylül 2026', 'Türkçe', 'Var', 'green'], ['12 Eylül 2026', 'Kimya', 'Yok', 'rose'], ['10 Eylül 2026', 'Fizik', 'Geç', 'amber']].map(([date, subject, status, tone]) => <Card key={date} className="flex items-center gap-3 p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-slate-50 text-slate-500"><CalendarDays size={17} /></div><div className="flex-1"><p className="text-sm font-bold text-slate-800">{date}</p><p className="mt-1 text-xs text-slate-400">{subject}</p></div><Badge tone={tone as 'green' | 'rose' | 'amber'}>{status}</Badge></Card>)}</div></>; }
function ParentHomework() { return <><SectionHeading eyebrow="Ahmet Yılmaz · 9A" title="Ödev Takibi" description="Ödevlerin güncel durumunu görün." /><div className="space-y-3">{homework.map((item) => <Card key={item.id} className="p-4"><div className="flex items-center gap-3"><div className={`grid h-10 w-10 place-items-center rounded-xl ${item.status === 'Tamamlandı' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'}`}><BookOpen size={18} /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><p className="truncate text-sm font-bold text-slate-800">{item.title}</p><Badge tone={item.status === 'Tamamlandı' ? 'green' : 'amber'}>{item.status}</Badge></div><p className="mt-1 text-xs text-slate-400">{item.subject} · Son teslim {item.due}</p></div></div></Card>)}</div></>; }
function ParentGrades() { return <><SectionHeading eyebrow="Ahmet Yılmaz · 9A" title="Deneme & Notlar" description="Sınav sonuçlarını ve gelişim özetini inceleyin." /><div className="space-y-3">{[['1. Dönem Deneme', 'Net 32', '412 Puan', 'green'], ['2. Deneme', 'Net 28', '386 Puan', 'blue'], ['Türkçe Sınavı', '92', '100 Üzerinden', 'amber']].map(([title, net, score, tone], index) => <Card key={title} className="flex items-center gap-3 p-4"><div className={`grid h-11 w-11 place-items-center rounded-2xl bg-${tone}-50 text-${tone}-600 text-lg font-bold`}>{index + 1}</div><div className="flex-1"><p className="text-sm font-bold text-slate-800">{title}</p><p className="mt-1 text-xs text-slate-400">{net} · {score}</p></div><ChevronRight size={16} className="text-slate-300" /></Card>)}<Card className="p-5"><p className="font-bold text-slate-900">Koçluk notu</p><p className="mt-2 text-sm leading-6 text-slate-500">Düzenli çalışmaya devam etmeli. Matematikteki gelişimi olumlu yönde ilerliyor.</p></Card></div></>; }
function Notifications() { return <><SectionHeading eyebrow="Güncel bilgiler" title="Bildirimler" description="Okuldan gelen son duyurular." /><div className="space-y-3">{initialAnnouncements.map((item, index) => <Card key={item.id} className="flex items-start gap-3 p-4"><div className={`grid h-10 w-10 place-items-center rounded-xl ${index === 1 ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}><Bell size={17} /></div><div className="flex-1"><div className="flex justify-between gap-3"><p className="text-sm font-bold text-slate-800">{item.title}</p><span className="h-2 w-2 rounded-full bg-emerald-500" /></div><p className="mt-1 text-xs text-slate-400">{item.date}</p><p className="mt-2 text-xs leading-5 text-slate-500">Okul yönetimi tarafından paylaşılan güncel duyuru.</p></div></Card>)}</div></>; }

function EmptyState({ label }: { label: string }) { return <div className="p-10 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-slate-100 text-slate-400"><FileText size={20} /></div><p className="mt-3 text-sm font-medium text-slate-500">{label}</p></div>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-30 grid place-items-center bg-slate-900/25 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-3xl bg-white p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h3 className="text-xl font-bold text-slate-900">{title}</h3><IconButton onClick={onClose}><X size={18} /></IconButton></div>{children}</div></div>; }

function App() { const [user, setUser] = useState<User | null>(null); const [desktopPage, setDesktopPage] = useState<DesktopPage>('schools'); const [adminPage, setAdminPage] = useState<DesktopPage>('overview'); const [mobilePage, setMobilePage] = useState<MobilePage>('attendance'); const logout = () => setUser(null); if (!user) return <Login onLogin={(loggedUser) => { setUser(loggedUser); if (loggedUser.role === 'teacher') setMobilePage('attendance'); if (loggedUser.role === 'parent') setMobilePage('parentOverview'); }} />; if (user.role === 'superadmin') return <SuperAdmin user={user} page={desktopPage} setPage={setDesktopPage} onLogout={logout} />; if (user.role === 'admin') return <Admin user={user} page={adminPage} setPage={setAdminPage} onLogout={logout} />; if (user.role === 'teacher') return <Teacher user={user} page={mobilePage} setPage={setMobilePage} onLogout={logout} />; return <Parent user={user} page={mobilePage} setPage={setMobilePage} onLogout={logout} />; }

export default App;
